'use strict';
const UI2={bind,peopleView,rivalsView,roastersView,storesView,help,report,financeView};
let menuStore=state.stores[0].id,planningKind='store',planningResult=null,planDraft=null;
const FOCUS={operations:'Provoz',people:'Vedení lidí',product:'Káva a produkt'},LAYOUT={balanced:'Vyvážený provoz',speed:'Rychlá obsluha',lounge:'Pohodlí a komunita'};
function storeOptions(value){return state.stores.map(s=>option(s.id,loc(s.id).city+' · '+loc(s.id).name,value)).join('')}
function empty(text){return `<p class="empty sub">${text}</p>`}
function menuView(){const s=state.stores.find(s=>s.id===menuStore)||state.stores[0];menuStore=s.id;const m=menuSummary(s),e=equipmentEffects(s);return `<div class="view-toolbar"><p class="intro">Ceny, nabídka i rychlost přípravy mění výsledek konkrétní kavárny. Manažer upravuje ceny jen s tvým povolením.</p>${field('Kavárna',`<select id="menuStore">${storeOptions(s.id)}</select>`)}</div><div class="split"><section class="card"><div class="card-head"><div><span class="eyelabel">${loc(s.id).city.toUpperCase()}</span><h2>Menu · ${loc(s.id).name}</h2></div><span class="badge">${m.drinks.length} nápojů</span></div><div class="table-scroll"><table class="data menu-table"><thead><tr><th>Položka / příprava</th><th>V nabídce</th><th>Cena Kč</th><th>Minulý prodej</th></tr></thead><tbody>${Object.entries(MENU).map(([k,c])=>{const item=s.menu[k],missing=c.requires&&!s.equipment[c.requires],last=s.lastItems.find(i=>i.id===k);return `<tr><td><strong>${c.name}</strong><small class="table-sub">${number(c.minutes,2)} min · suroviny ${money(c.cost)}${c.dose?' + '+number(c.dose*1000,0)+' g kávy':''}${missing?'<br>Potřebuješ: '+EQUIPMENT[c.requires].name:''}</small></td><td><input aria-label="Nabízet ${c.name}" type="checkbox" data-menu-item="${k}" data-menu-key="enabled" ${item.enabled?'checked':''} ${missing?'disabled':''}></td><td><input aria-label="Cena ${c.name}" type="number" min="35" max="350" value="${item.price}" data-menu-item="${k}" data-menu-key="price"></td><td>${last?number(last.count)+' ks':'—'}</td></tr>`}).join('')}</tbody></table></div><p class="sub">Jídlo kupuje část hostů navíc k nápoji. Mix nápojů se mění podle lokality a sezóny; prodeje jednotlivých položek jsou rozdělení celkového počtu hostů.</p>${!m.hasDrinks?'<div class="warning">Bez aktivního nápoje kavárna neobslouží hosty. Zapni alespoň espresso.</div>':''}</section><section class="card"><h2>Provozní model</h2>${rows([['Průměrná cena nápoje',money(m.price)],['Jídlo navíc / host',money(m.foodRevenue)],['Suroviny / host',money(m.cost+m.foodCost)],['Káva / host',number(m.dose*1000,1)+' g'],['Čas přípravy / host',number(m.minutes,2)+' min'],['Vliv vybavení na kapacitu','+'+round((e.capacity-1)*100)+' %'],['Údržba zařízení / týden',money(e.cost)],['Kvalita obsluhy',round(s.serviceCondition)+'/100'],['Místa k sezení',s.seats]])}${field('Uspořádání (změna 25 000 Kč)',`<select id="storeLayout">${Object.entries(LAYOUT).map(([k,v])=>option(k,v,s.layout)).join('')}</select>`)}<p class="sub">Rychlý bar zvýší kapacitu o 13 %. Pohodlné sezení přitáhne komunitní hosty o 10 %, ale obsluha je o 10 % pomalejší.</p><button class="soft" data-goto="stores">Tým, cena a značka →</button></section></div><div class="section-header"><div><span class="eyelabel">INVESTICE DO PROVOZU</span><h2>Vybavení & prostor</h2></div></div><div class="cards">${Object.entries(EQUIPMENT).map(([k,c])=>{const installed=s.equipment[k];return `<section class="card equipment-card"><span class="badge">${installed?'Instalováno · '+round(installed.condition)+' %':'Nová investice'}</span><h3>${c.name}</h3><p class="sub">${c.capacity>1?'Kapacita až +'+round((c.capacity-1)*100)+' %. ':''}${c.quality?'Kvalita +'+c.quality+'. ':''}${k==='seats'?'Dvanáct míst navíc. ':''}Údržba ${money(c.maintenance)} / týden.</p><button class="${installed?'soft':'primary'} wide" ${!installed&&state.cash<c.cost?'disabled':''} data-equipment="${k}" data-equipped="${!!installed}">${installed?'Servis · '+money(round(c.cost*.08)):'Pořídit · '+money(c.cost)}</button></section>`}).join('')}</div>`}
function logisticsView(){return `<div class="view-toolbar"><p class="intro">Káva má fyzické zásoby v každém městě. Trasy přepravují šarže se zachovaným stářím a náklady.</p><div class="actions"><button class="soft" id="newWarehouse">Koupit sklad +</button><button class="primary" id="newRoute">Nová trasa +</button></div></div><div class="split"><section class="card"><h2>Způsob zásobování</h2>${field('Pokrytí chybějících místních zásob',`<select id="deliveryPolicy">${option('express','Expresně z jiných měst · 12–38 Kč/kg',state.deliveryPolicy)}${option('planned','Pouze místní zásoby a naplánované trasy',state.deliveryPolicy)}</select>`)}<p class="sub">Expres zachrání prodeje, ale platíš přepravu. U plánovaných tras kavárna bez místní kávy ztrácí hosty. Pražírnu můžeš otevřít přímo ve městě odběru.</p><table class="data"><thead><tr><th>Město</th><th>Pražená káva</th><th>Kapacita</th></tr></thead><tbody>${CITIES.filter(c=>state.warehouses.some(w=>w.zone===c.name)||state.stores.some(s=>loc(s.id).city===c.name)||cityStock(c.name)>0).map(c=>`<tr><td>${c.name}</td><td>${number(cityStock(c.name),1)} kg</td><td>${number(warehouseCapacity(c.name))} kg</td></tr>`).join('')}</tbody></table></section><section class="card"><h2>Distribuční sklady</h2>${state.warehouses.map(w=>`<div class="news"><span class="news-icon">▦</span><div><strong>${esc(w.name)}</strong><small>${w.zone} · ${number(w.capacity)} kg · ${money(w.upkeep)}/týden</small></div></div>`).join('')}<p class="sub">Každé město má i 150 kg malého provozního skladu. Sklady poskytují další kapacitu; plný sklad pozastaví pražení nebo vykládku.</p></section></div><div class="section-header"><h2>Zásobovací trasy</h2></div><div class="cards">${state.routes.map(r=>{const p=transportProfile(r.from,r.to,r.mode);return `<section class="card"><span class="badge">${r.active?'Aktivní':'Pozastavená'}</span><h3>${r.from} → ${r.to}</h3><p>${esc(blend(r.blend).name)} · max. ${r.kg} kg/týden</p>${rows([['Přeprava',r.mode==='air'?'Expresní':'Standardní'],['Doba přepravy',p.weeks+' týden/týdny'],['Cena / kg',money(p.cost)],['Poslední odeslání',r.last?number(r.last.kg,1)+' kg · '+money(r.last.cost):'—']])}${r.last?`<p class="sub">${esc(r.last.reason)}</p>`:''}<button class="soft wide" data-route-toggle="${r.id}">${r.active?'Pozastavit':'Obnovit'} trasu</button></section>`}).join('')||empty('Pořiď cílový sklad a založ první trasu. Automatika praží ve zdrojovém městě také pro odběry tras.')}</div><section class="card" style="margin-top:24px"><h3>Pražená káva na cestě</h3>${state.transfers.map(t=>`<div class="row"><span>${t.from} → ${t.to} · ${esc(blend(t.blend).name)}</span><strong>${number(t.kg,1)} kg · týden ${t.due}</strong></div>`).join('')||empty('Žádná přeprava právě neprobíhá.')}</section><section class="card" style="margin-top:24px"><div class="card-head"><h2>Dlouhodobé dodávky zelené kávy</h2><button class="soft" id="newSupply">Smlouva s dodavatelem +</button></div><p class="sub">Zřízení 35 000 Kč. Dodavatel posílá 20–500 kg týdně na 16 týdnů za pevnou cenu se slevou 13 %. Dodávka přijede další týden; automatika zachová rezervu.</p>${state.supplyDeals.map(d=>`<div class="row"><span>${ORIGINS[d.origin].name} · ${d.kg} kg/týden · ${money(d.price)}/kg · zbývá ${d.remaining} t.</span><button class="soft mini" data-supply-toggle="${d.id}">${d.active?'Pozastavit':'Obnovit'}</button></div>`).join('')||empty('Zatím nakupuješ jednorázově nebo expresně při pražení.')}<div class="recipe-line">${Object.entries(ORIGINS).map(([k,o])=>`<span>${o.name.split(' · ')[0]} · ${money(getBeanCost(k))}/kg</span>`).join('')}</div></section>`}
function crisesView(){return `<div class="split"><section class="card"><span class="eyelabel">ROZHODOVACÍ PRAVOMOCI</span><h2>Vedení, kterému můžeš věřit</h2><label class="checkbox-line"><input id="autoCrises" type="checkbox" ${state.policy3.autoCrises?'checked':''}> Manažeři mohou řešit provozní problémy</label>${field('Maximální jednorázový výdaj (Kč)',input('crisisLimit',state.policy3.crisisLimit,0,100000,1000))}<p class="sub">Samostatně rozhoduje vedoucí s dovedností 75+, oblastní ředitel 80+ nebo Obchod u dodávek. Potřebuje dvojnásobek fixních nákladů jako rezervu. Preventivní servis také respektuje tento limit.</p><label class="checkbox-line"><input id="autoRetention" type="checkbox" ${state.policy3.autoRetention?'checked':''}> HR smí dorovnat nabídku konkurence</label>${field('Nejvyšší týdenní mzda při dorovnání (Kč)',input('retentionLimit',state.policy3.retentionLimit,0,50000,500))}<p class="sub">HR potřebuje zaměstnance a třítýdenní hotovostní rezervu. Bez oprávnění zůstává rozhodnutí tobě.</p></section><section class="card"><h2>Co čeká na rozhodnutí</h2>${rows([['Otevřené problémy',state.incidents.length],['Nabídky pro tvé lidi',state.offers.length],['Vyřešeno vedením',state.incidentHistory.filter(i=>i.automatic&&i.choice!=='wait').length],['Poslední náklad problémů',money(state.history.at(-1)?.detail.crises||0)]])}<p class="sub">Každý problém ukazuje následek a termín. Po jeho uplynutí se uplatní varianta bez zásahu. Deník uchová zvolené řešení.</p><button class="soft" data-goto="people">Kariéry a spokojenost →</button></section></div><div class="section-header"><h2>Provozní problémy</h2></div><div class="cards">${state.incidents.map(i=>`<section class="card incident-card"><span class="badge">Rozhodni do týdne ${i.due}</span><h3>${esc(i.title)}</h3><p>${esc(i.details)}</p><div class="stack">${CRISIS_CHOICES[i.type].map(c=>`<button class="${c.id==='wait'?'soft':'primary'}" data-incident="${i.id}" data-solution="${c.id}" ${state.cash<c.cost?'disabled':''}>${c.label} · ${money(c.cost)}</button>`).join('')}</div></section>`).join('')||empty('Provoz je nyní bez otevřených problémů. Nové události přicházejí podle obtížnosti každých 4–8 týdnů.')}</div>${offersPanel()}<section class="card" style="margin-top:24px"><h3>Deník řešení</h3>${state.incidentHistory.slice(0,12).map(i=>`<div class="news"><span class="news-icon">${i.automatic?'↗':'✓'}</span><div><strong>${esc(i.title)}</strong><small>Týden ${i.resolvedWeek} · ${i.automatic?'Automaticky':'Tvoje rozhodnutí'} · ${CRISIS_CHOICES[i.type].find(c=>c.id===i.choice)?.label||'Vyřešeno'} · ${money(i.cost)}</small></div></div>`).join('')||empty('Po první události uvidíš, kdo rozhodl, jak a za kolik.')}</section>`}
function offersPanel(){return state.offers.length?`<section class="card" style="margin-top:24px"><h2>Přetahování talentů</h2>${state.offers.map(o=>{const p=staffAssignments().find(a=>a.person.pid===o.pid)?.person;return `<div class="offer"><h3>${esc(o.name)}</h3><p>${esc(state.rivals.find(r=>r.id===o.rival)?.name)} nabízí ${money(o.salary)}/týden. Termín ${o.due}. Spokojenost ${round(p?.satisfaction||0)}/100.</p><div class="actions"><button class="primary" data-offer="${o.id}" data-answer="match">Dorovnat mzdu</button><button class="soft" data-offer="${o.id}" data-answer="stay">Spolehnout na loajalitu</button><button class="soft" data-offer="${o.id}" data-answer="leave">Umožnit odchod</button></div><p class="sub">Bez dorovnání zůstane při spokojenosti alespoň 75. Při nižší může odejít.</p></div>`}).join('')}</section>`:''}
const PLAN_NAMES={store:'Nová kavárna',roaster:'Pražírna',estate:'Plantáž',office:'Kanceláře',warehouse:'Distribuční sklad',equipment:'Vybavení kavárny'};
function planTargets(kind,value){const list=kind==='store'?LOCATIONS.filter(l=>!owned(l.id)&&!occupant(l.id)).map(l=>({id:l.id,label:l.city+' · '+l.name+' · '+money(l.setup)+(unlocked(l.city)?'':' · město uzamčeno')})):kind==='roaster'?ROASTER_OPTIONS.map(o=>({id:o.id,label:o.name+' · '+money(o.cost)})):kind==='estate'?ESTATES.filter(e=>!state.estates.some(s=>s.sourceId===e.id)).map(o=>({id:o.id,label:o.name+' · '+money(o.cost)})):kind==='office'?OFFICE_OPTIONS.map(o=>({id:o.id,label:o.name+' · '+money(o.cost)})):kind==='equipment'?Object.entries(EQUIPMENT).map(([id,e])=>({id,label:e.name+' · '+money(e.cost)})):[];return list.map(o=>option(o.id,o.label,value)).join('')}
function plannerView(){const p=planDraft||{};return `<p class="intro">Před investicí přehraj budoucí týdny v oddělené kopii firmy. Včetně mezd, pražení, zásob, krizí a rozhodnutí soupeřů.</p><div class="split"><section class="card"><span class="eyelabel">DALŠÍ KROK FIRMY</span><h2>Investiční plán</h2><div class="fields">${field('Typ investice',`<select id="planKind">${Object.entries(PLAN_NAMES).map(([k,v])=>option(k,v,planningKind)).join('')}</select>`)}${planningKind!=='warehouse'?field('Cíl investice',`<select id="planTarget">${planTargets(planningKind,p.target)}</select>`):field('Velikost skladu',`<select id="planSize">${[1000,3000,6000].map(n=>option(n,number(n)+' kg · '+money(n*95),p.size||1000)).join('')}</select>`)}${['warehouse','roaster'].includes(planningKind)?field('Město',`<select id="planCity">${cityOptions(p.city||city)}</select>`):''}${planningKind==='equipment'?field('Kavárna',`<select id="planStore">${storeOptions(p.store||menuStore)}</select>`):''}${planningKind==='store'?field('Značka',`<select id="planBrand">${brandOptions(p.brand||state.brands[0].id)}</select>`)+field('Směs',`<select id="planBlend">${blendOptions(p.blend||state.blends[0].id)}</select>`):''}${field('Horizont',`<select id="planWeeks">${[4,8,12,26].map(n=>option(n,n+' týdnů',planningResult?.weeks||8)).join('')}</select>`)}</div><button class="primary wide" id="runPlan" style="margin-top:18px">Spočítat tři varianty →</button><p class="sub">Opatrná poptávka −18 %, základní stav, příznivá +12 %. Tvoje ruční úpravy během výhledu nejsou zahrnuty. Výsledek je odhad herního modelu.</p></section><section class="card guide"><span class="eyelabel">INVESTIČNÍ DISCIPLÍNA</span><h2>Rozšiřuj i zázemí.</h2>${rows([['Hotovost dnes',money(state.cash)],['Fixní náklady / týden',money(weeklyFixed())],['Rezerva na šest týdnů',money(weeklyFixed()*6)],['Odhad hodnoty firmy',money(companyValue())]])}<p>Nové pobočky potřebují lidi a kávu. Výroba potřebuje prostor a zrna. Plantáže spotřebovávají hotovost před první sklizní. Plánovač tyto souvislosti počítá.</p></section></div>${planningResult?planResults():''}`}
function planResults(){const r=planningResult,max=Math.max(1,...r.results.flatMap(v=>v.series.map(s=>Math.abs(s.cash))));return `<section class="card forecast-panel" style="margin-top:24px"><div class="card-head"><div><span class="eyelabel">VÝHLED Z TÝDNE ${r.week} · ${r.weeks} TÝDNŮ</span><h2>${PLAN_NAMES[r.plan.kind]}</h2></div><button class="primary" id="commitPlan" ${state.week!==r.week||state.over?'disabled':''}>Provést tuto investici</button></div><div class="table-scroll"><table class="data"><thead><tr><th>Varianta</th><th>Investice</th><th>Hotovost na konci</th><th>Nejnižší hotovost</th><th>Zisk za období</th></tr></thead><tbody>${r.results.map(v=>`<tr><td><strong>${v.name}</strong><small class="table-sub">Poptávka ${round(v.factor*100)} %${v.over?' · platební neschopnost':''}</small></td><td>${money(v.investment)}</td><td class="${v.cash>=0?'good':'bad'}">${money(v.cash)}</td><td>${money(v.minCash)}</td><td class="${v.profit>=0?'good':'bad'}">${money(v.profit)}</td></tr>`).join('')}</tbody></table></div><svg class="forecast-chart" viewBox="0 0 720 180" role="img" aria-label="Vývoj hotovosti ve třech variantách"><line x1="20" y1="160" x2="700" y2="160" stroke="#d9ddcf"/>${r.results.map((v,i)=>`<polyline fill="none" stroke="${['#b86748','#254b3b','#91a457'][i]}" stroke-width="3" points="${v.series.map((s,n)=>(20+n/Math.max(1,r.weeks-1)*680)+','+(150-Math.max(0,s.cash)/max*125)).join(' ')}"/>`).join('')}</svg><p class="sub">${r.results.map((v,i)=>`<span class="legend-item" style="color:${['#b86748','#254b3b','#91a457'][i]}">● ${v.name}</span>`).join('')} Zobrazená hotovost se mění také nákupem zásob a kapitálovými výdaji. Před provedením se znovu ověří aktuální dostupnost a hotovost.</p></section>`}
function readPlan(){return {kind:planningKind,target:el('planTarget')?.value,city:el('planCity')?.value,store:el('planStore')?.value,size:Number(el('planSize')?.value||1000),brand:el('planBrand')?.value,blend:el('planBlend')?.value};}
function scenariosView(){const p=scenarioProgress(),sc=SCENARIOS[state.scenario];return `<div class="split"><section class="card guide"><span class="eyelabel">${state.scenarioWon?'SCÉNÁŘ DOKONČEN':'TVŮJ PŘÍBĚH'}</span><h2>${sc.name}</h2><p>${sc.description}</p>${rows([['Obtížnost',DIFFICULTIES[state.difficulty].name],['Pobočky',state.stores.length+' / '+p.stores],['Města',new Set(state.stores.map(s=>loc(s.id).city)).size+' / '+p.cities],...(state.scenario==='rescue'?[]:[['Pověst',state.reputation+' / '+p.rep]]),['Poslední čtyři týdny ziskové',p.profitable?'Ano':'Zatím ne'],...(state.scenario==='rescue'?[['Dluh',money(state.debt)+' / cíl ≤500 000 Kč']]:[])])}<button class="soft wide" id="chooseScenario">Vybrat novou kampaň</button></section><section class="card"><h2>Vyber si způsob hraní</h2>${Object.entries(DIFFICULTIES).map(([k,d])=>`<div class="news"><span class="news-icon">${k==='expert'?'◆':k==='normal'?'◇':'○'}</span><div><strong>${d.name}</strong><small>Poptávka ${round(d.demand*100)} % · událost každých ${d.eventEvery} týdnů · soupeři expandují každé ${d.rivalEvery} týdny</small></div></div>`).join('')}<p class="sub">Obtížnost volíš na začátku kampaně. Splnění cíle ponechá firmu otevřenou pro další rozvoj.</p></section></div><div class="section-header"><h2>Čtyři začátky, jedno kávové impérium</h2></div><div class="cards">${Object.entries(SCENARIOS).map(([k,s])=>`<section class="card"><span class="badge">${k===state.scenario?'Rozehráno':money(s.cash)+' kapitálu'}</span><h3>${s.name}</h3><p>${s.description}</p><p class="sub">${s.debt?'Počáteční dluh '+money(s.debt):'Bez počátečního dluhu'} · pověst ${s.rep}.</p><button class="soft" data-new-scenario="${k}">Začít tuto kampaň →</button></section>`).join('')}</div>`}
milestone=function(){const p=scenarioProgress(),s=SCENARIOS[state.scenario];return `<section class="card guide"><span class="eyelabel">${state.scenarioWon?'CÍL SPLNĚN':'CÍL KAMPANĚ'}</span><h3 style="margin-top:12px">${s.name}</h3><p>${s.description}</p><div class="bar"><i style="width:${Math.min(100,state.stores.length/p.stores*100)}%"></i></div><small>${state.scenario==='rescue'?'Dluh '+money(state.debt)+' / cíl ≤500 000 Kč':state.stores.length+'/'+p.stores+' poboček · pověst '+state.reputation+'/'+p.rep}</small><button class="quiet" data-goto="scenarios">Průběh kampaně →</button></section>`};
peopleView=function(){return UI2.peopleView()+`<div class="section-header"><div><span class="eyelabel">LIDÉ S VLASTNÍ KARIÉROU</span><h2>Rozvoj vedení</h2></div><span class="badge">${staffAssignments().length} lidí ve vedení</span></div><div class="cards">${staffAssignments().map(a=>{const p=a.person;return `<section class="card"><span class="badge">${esc(a.label)} · ${a.kind==='region'?'Ředitel':a.kind==='roaster'?'Výroba':a.kind==='estate'?'Plantáž':a.kind==='executive'?'Vedení oddělení':'Kavárna'}</span><h3>${esc(p.name)}</h3>${rows([['Spokojenost',round(p.satisfaction)+'/100'],['Mzda / týden',money(p.salary*(a.kind==='region'?1.4:a.kind==='executive'?1.35:1))],['Ve firmě',p.tenure+' týdnů'],['Zkušenosti k dalšímu bodu',number(p.xp,1)+' / 20'],...Object.entries(p.strength).map(([k,v])=>[FOCUS[k],round(v)+'/100'])])}<div class="bar"><i style="width:${p.satisfaction}%"></i></div><div class="actions"><button class="soft mini" data-train="${p.pid}">Školení · ${money(state.departments.hr?12000:18000)}</button><button class="soft mini" data-raise="${p.pid}" ${p.salary>=50000?'disabled':''}>Mzda +12 %</button>${a.kind!=='region'?`<button class="soft mini" data-promote="${p.pid}">Povýšit do regionu</button>`:''}</div>${p.history.length?`<details><summary>Kariérní historie</summary><p class="sub">${p.history.slice(0,5).map(h=>'Týden '+h.week+' · '+esc(h.text)).join('<br>')}</p></details>`:''}</section>`}).join('')||empty('Najmi vedoucího kavárny, výroby nebo plantáže. Kariéra pokračuje i po povýšení.')}</div>${offersPanel()}<section class="card" style="margin-top:24px"><h3>Trh práce</h3><p class="sub">${state.talents.length} dostupných kandidátů. Nový kandidát přichází každých pět týdnů. Každá osoba drží svoje zkušenosti a spokojenost; nelze zaměstnat tutéž osobu ve dvou provozech.</p>${rows(state.talents.map(p=>[esc(p.name),p.skill+'/100 · '+money(p.salary)+'/týden']))}</section>`};
rivalsView=function(){return `<div class="split"><section class="card"><span class="eyelabel">NÁJEMNÍ PRÁVA</span><h2>Aukce prémiových adres</h2><p class="sub">Nová aukce každých osm týdnů. Soupeři přihazují z vlastní hotovosti. Výherce platí příplatek za nájemní právo; otevření se platí zvlášť.</p>${state.auctions.filter(a=>!a.closed).map(a=>`<div class="offer"><h3>${loc(a.location).city} · ${loc(a.location).name}</h3>${rows([['Nejvyšší příhoz',money(a.highest)],['Vede',a.leader==='player'?'Tvoje firma':esc(state.rivals.find(r=>r.id===a.leader)?.name||'Zatím nikdo')],['Uzavření', 'Týden '+a.due],['Cena otevření',money(loc(a.location).setup)]])}<button class="primary wide" data-bid="${a.id}" ${state.cash<a.highest+10000+loc(a.location).setup?'disabled':''}>Přihodit 10 000 Kč →</button></div>`).join('')||empty('Další dražba přijde v týdnu '+(Math.floor(state.week/8)+1)*8+'.')} ${state.market3.exclusive.filter(e=>e.location&&e.holder==='player').map(e=>`<div class="warning">Vyhrál jsi ${loc(e.location).name}. Právo platí do týdne ${e.until}. <button class="soft mini" data-open="${e.location}">Otevřít kavárnu</button></div>`).join('')}</section><section class="card"><span class="eyelabel">KAPITÁL & NABÍDKY</span><h2>Hodnota vlastní firmy</h2>${rows([['Odhad hodnoty',money(companyValue())],['Podíl zakladatele',state.founderShare+' %']])}${state.buyout?`<div class="warning"><strong>${esc(state.rivals.find(r=>r.id===state.buyout.rival)?.name)} nabízí ${money(state.buyout.amount)}.</strong><p>Platí do týdne ${state.buyout.due}. Prodejem končí tato kampaň; zakladatel získá ${money(state.buyout.amount*state.founderShare/100)}.</p><div class="actions"><button class="primary" id="acceptBuyout">Prodat firmu</button><button class="soft" id="declineBuyout">Odmítnout</button></div></div>`:empty('Silní soupeři mohou každých 16 týdnů nabídnout odkup podle hodnoty firmy a vlastních prostředků.')}<h3 style="margin-top:20px">Prioritní dodávky konkurence</h3>${state.market3.exclusive.filter(e=>e.origin).map(e=>`<p class="sub">${esc(state.rivals.find(r=>r.id===e.holder)?.name)} · ${ORIGINS[e.origin].name} · běžné nákupy +12 % do týdne ${e.until}.</p>`).join('')||empty('Zatím nejsou omezené žádné původy.')}<p class="sub">Rámcové smlouvy drží pevnou cenu. Vlastní plantáž chrání část výroby před zdražením trhu.</p></section></div><div class="section-header"><h2>Tvůj trh a soupeři</h2></div>${UI2.rivalsView()}`};
roastersView=function(){return `<section class="card" style="margin-bottom:24px"><h3>Výroba v jednotlivých městech</h3>${rows(state.roasters.map(r=>[esc(r.name),r.zone+' · potřeba '+number(Object.values(productionNeeds(r.zone)).reduce((a,n)=>a+n,0),1)+' kg / týden']))}<p class="sub">Každá pražírna vyrábí do svého městského skladu. Změnou města provozu přemístíš výrobní linku za 75 000 Kč; hotové zásoby zůstanou v původním skladu.</p><div class="fields">${state.roasters.map(r=>field(esc(r.name),`<select data-roaster-city="${r.id}">${cityOptions(r.zone)}</select>`)).join('')}</div></section>`+UI2.roastersView()};
storesView=function(){return `<div class="tutorial"><span>Nabídku, výdejní bar a zařízení teď řídíš pro každou kavárnu samostatně.</span><button class="soft mini" data-goto="menu">Menu & vybavení →</button></div>`+UI2.storesView()};
report=function(id){UI2.report(id);const s=state.stores.find(s=>s.id===id);el('modalContent').insertAdjacentHTML('beforeend',`<h3>Prodejní mix</h3>${rows(s.lastItems.map(i=>[MENU[i.id].name,number(i.count)+' ks · '+money(i.revenue)]))}<p class="sub">Prodejní mix rozděluje nápoje podle místních preferencí. Jídlo je dodatečný nákup části hostů.</p>`)};
hireDialog=function(id,kind){show(`<span class="eyelabel">NÁBOR VEDENÍ</span><h2>Vyber konkrétního člověka</h2><p>Nábor ${money(Math.max(4000,12000-state.departments.hr*1500))}. Jedna osoba může pracovat v jednom provozu.</p>${state.talents.map((p,i)=>`<div class="vote"><span class="avatar">${esc(p.initials)}</span><div style="flex:1"><strong>${esc(p.name)}</strong><small>${p.skill}/100 · ${money(p.salary)}/týden · spokojenost ${round(p.satisfaction)}</small></div><button class="soft mini" data-hire-choice="${i}" data-candidate="${p.pid}">Najmout</button></div>`).join('')||empty('Trh práce je prázdný. Další kandidát přijde v pátém týdnu cyklu.')}<button class="quiet" id="fireInDialog">Odvolat stávajícího manažera</button>`);on('[data-candidate]',b=>{try{hireCandidate(id,b.dataset.candidate,kind);persist();render();el('modal').close();toast('Manažer nastoupil.')}catch(e){toast(e.message)}});el('fireInDialog').onclick=()=>{act(()=>fire(id,kind),'Vedení odvoláno.');el('modal').close()};};
purchaseRoasterDialog=function(){show(`<span class="eyelabel">VÝROBA BLÍZKO HOSTŮ</span><h2>Koupit pražírnu</h2><div class="fields">${field('Název',`<input id="roasterName" maxlength="40" value="Nová pražírna">`)}${field('Město',`<select id="roasterCity">${cityOptions(city)}</select>`)}${field('Typ',`<select id="roasterType">${ROASTER_OPTIONS.map(o=>option(o.id,o.name+' · '+money(o.cost),'artisan')).join('')}</select>`)}</div><p class="sub">Kapacitu a provozní náklady si ověř v Plánovači. Pražení je omezené místním skladem, pracovníky, směnami a stavem linky.</p><button class="primary wide" id="roasterConfirm">Pořídit provoz</button>`);el('roasterConfirm').onclick=()=>{try{buyRoaster(el('roasterType').value,el('roasterName').value,el('roasterCity').value);persist();render();el('modal').close();toast('Výroba zahájena.')}catch(e){toast(e.message)}};};
function warehouseDialog(){show(`<h2>Distribuční sklad</h2><div class="fields">${field('Město',`<select id="warehouseCity">${cityOptions(city)}</select>`)}${field('Název',`<input id="warehouseName" maxlength="50" value="Regionální sklad">`)}${field('Kapacita',`<select id="warehouseSize">${[1000,3000,6000].map(n=>option(n,number(n)+' kg · '+money(n*95),1000)).join('')}</select>`)}</div><p class="sub">Provoz 0,95 Kč/kg kapacity týdně. Sklad slouží jako cíl tras i zásobník místní výroby.</p><button class="primary wide" id="warehouseConfirm">Koupit sklad</button>`);el('warehouseConfirm').onclick=()=>{try{buyWarehouse(el('warehouseCity').value,el('warehouseName').value,Number(el('warehouseSize').value));persist();render();el('modal').close();toast('Sklad pořízen.')}catch(e){toast(e.message)}};}
function routeDialog(){show(`<h2>Zásobovací trasa</h2><div class="fields">${field('Zdrojové město',`<select id="routeFrom">${cityOptions('Praha')}</select>`)}${field('Cílové město se skladem',`<select id="routeTo">${state.warehouses.map(w=>w.zone).filter((c,i,a)=>a.indexOf(c)===i).map(c=>option(c,c,c==='Praha'?'Brno':c)).join('')}</select>`)}${field('Káva',`<select id="routeBlend">${blendOptions(state.blends[0].id)}</select>`)}${field('Maximální množství / týden',input('routeKg',60,5,500))}${field('Způsob přepravy',`<select id="routeMode">${option('standard','Standardní · 1–2 týdny · 5–16 Kč/kg','standard')}${option('air','Expresní · 1 týden · 12–38 Kč/kg','standard')}</select>`)}</div><p class="sub">Založení 12 000 Kč. Trasa automaticky doplňuje cílovou zásobu a zachovává původní datum pražení. Nejprve potřebuješ sklad v cílovém městě.</p><button class="primary wide" id="routeConfirm">Spustit trasu</button>`);el('routeConfirm').onclick=()=>{try{createRoute(el('routeFrom').value,el('routeTo').value,el('routeBlend').value,Number(el('routeKg').value),el('routeMode').value);persist();render();el('modal').close();toast('Trasa spuštěna.')}catch(e){toast(e.message)}};}
function supplyDialog(){show(`<h2>Rámcová smlouva na zrna</h2><div class="fields">${field('Původ',`<select id="supplyOrigin">${Object.entries(ORIGINS).filter(([k])=>!state.supplyDeals.some(d=>d.origin===k)).map(([k,o])=>option(k,o.name+' · '+money(round(getBeanCost(k)*.87))+'/kg','brazil')).join('')}</select>`)}${field('Množství / týden',input('supplyKg',40,20,500))}</div><p class="sub">16 týdnů. Jednorázově 35 000 Kč a průběžná cena dodávek. Příjezd další týden. Nepotřebné dodávky můžeš pozastavit.</p><button class="primary wide" id="supplyConfirm">Podepsat smlouvu</button>`);el('supplyConfirm').onclick=()=>{try{signSupply(el('supplyOrigin').value,Number(el('supplyKg').value));persist();render();el('modal').close();toast('Dodávky sjednány.')}catch(e){toast(e.message)}};}
function trainingDialog(pid){show(`<h2>Rozvoj manažera</h2>${field('Zaměření',`<select id="trainFocus">${Object.entries(FOCUS).map(([k,v])=>option(k,v,'operations')).join('')}</select>`)}<p>Vybraná dovednost +4, zkušenosti +15 a spokojenost +5. Celková dovednost je průměr tří zaměření.</p><button class="primary wide" id="trainConfirm">Školení · ${money(state.departments.hr?12000:18000)}</button>`);el('trainConfirm').onclick=()=>{const r=act(()=>trainPerson(pid,el('trainFocus').value),'Školení dokončeno.');el('modal').close()};}
function promotionDialog(pid){show(`<h2>Povýšit do regionálního vedení</h2>${field('Region',`<select id="promoteCity">${CITIES.filter(c=>!state.regions.some(r=>r.city===c.name)).map(c=>option(c.name,c.name,city)).join('')}</select>`)}<p>Povýšení 20 000 Kč, místo v centrále a čtyři týdny ve firmě nebo dovednost 85+. Člověk opustí svůj provoz a zachová zkušenosti. Regionální mzda je 1,4× základ.</p><button class="primary wide" id="promoteConfirm">Povýšit</button>`);el('promoteConfirm').onclick=()=>{try{promotePerson(pid,el('promoteCity').value);persist();render();el('modal').close();toast('Regionální vedení převzato.')}catch(e){toast(e.message)}};}
confirmNew=function(scenario='sandbox'){show(`<span class="eyelabel">NOVÁ KAMPAŇ</span><h2>Jak začne tvoje firma?</h2><p>Současný postup v prohlížeči se nahradí. Nejdřív ho můžeš uložit do souboru.</p><div class="fields">${field('Začátek',`<select id="newScenario">${Object.entries(SCENARIOS).map(([k,s])=>option(k,s.name,typeof scenario==='string'?scenario:'sandbox')).join('')}</select>`)}${field('Obtížnost',`<select id="newDifficulty">${Object.entries(DIFFICULTIES).map(([k,s])=>option(k,s.name,'normal')).join('')}</select>`)}</div><p id="scenarioDescription" class="warning"></p><div class="actions"><button class="soft" id="saveBeforeReset">Uložit současnou hru</button><button class="primary" id="resetConfirm">Začít tuto kampaň</button></div>`);const preview=()=>el('scenarioDescription').textContent=SCENARIOS[el('newScenario').value].description;el('newScenario').onchange=preview;preview();el('saveBeforeReset').onclick=downloadSave;el('resetConfirm').onclick=()=>{state=fresh(el('newScenario').value,el('newDifficulty').value);view='city';city='Praha';selected=state.stores[0].id;menuStore=selected;planningResult=null;planDraft=null;filterCity='all';notice='';persist();render();el('modal').close();toast('Nová kampaň: '+SCENARIOS[state.scenario].name);window.scrollTo({top:0})};};
help=function(){show(`<span class="eyelabel">KAVÁRNA · EDICE 03</span><h2>Od rodinné kavárny po světovou firmu</h2><p>Každý tah je jeden týden. Hra nejprve přijme dodávky, řeší povolené problémy, vyrobí a odešle kávu, obslouží hosty a zaplatí skutečné náklady. Soupeři, kariéry a nové události pokračují spolu s tebou.</p><p><strong>Začátek:</strong> otevři druhou pobočku s rezervou, najmi vedoucího a sleduj její výsledek. Po dvou pobočkách a pověsti 45 se otevře Brno. V dalších městech platí vlastní podmínky.</p><p><strong>Provoz:</strong> Menu mění cenu, spotřebu a čas přípravy. Vybavení zvyšuje kapacitu nebo umožní nové položky. Bar, sezení a směny mají náklady. Prodejní mix najdeš v reportu kavárny.</p><p><strong>Výroba:</strong> receptury mají vlastní šarže. Pražírny vyrábějí do místního skladu podle odběru kaváren a tras. Zrna objednej dopředu; expresní nákup je dražší. Plantáž potřebuje financovat růst před sklizní.</p><p><strong>Logistika:</strong> každý sklad a každá cesta drží konkrétní šarže. Trasy dodávají za 1–2 týdny a nemění datum pražení. Starší káva ztrácí chuť a osm týdnů stará se odpisuje. Expresní pokrytí chrání prodeje za příplatek.</p><p><strong>Lidé:</strong> vedoucí má vlastní zkušenosti, dovednosti a spokojenost. Škol, zvyšuj mzdu nebo povyšuj. Regionální vedení potřebuje kanceláře. HR pomáhá rozvoji a může dorovnat konkurenční nabídku v limitu.</p><p><strong>Problémy:</strong> porucha, výpadek lidí, reklamace či zpoždění mají dopady a termín. Vedení rozhoduje jen v povoleném rozpočtu a s rezervou; jinak rozhoduješ ty.</p><p><strong>Expanze:</strong> osmnáct měst, tři soupeři, dražby adres, akvizice a nabídky na odkup tvé firmy. Board má zveřejněná pravidla. Centrála propojuje HR, Finance, Obchod, Produkt a IT s platy a kapacitou kanceláří.</p><p><strong>Plánovač:</strong> před investicí spočítej opatrnou, základní a příznivou variantu 4–26 týdnů. Hru to neposune. Vybranou investici pak můžeš skutečně provést.</p><p><strong>Kampaně:</strong> čtyři scénáře a tři obtížnosti mají různé začátky a cíle. Po dokončení pokračuješ. Ekonomika je herní model v Kč, bez daní a účetních odpisů investic.</p><p class="sub">Postup se ukládá v tomto prohlížeči. Export slouží pro zálohu a přenos. Starší verze se automaticky převedou.</p><div class="actions"><button class="soft" id="helpSave">Uložit soubor</button><button class="soft" id="helpImport">Načíst soubor</button><button class="soft" id="helpReset">Nová kampaň</button></div>`);el('helpSave').onclick=downloadSave;el('helpImport').onclick=()=>el('import').click();el('helpReset').onclick=()=>confirmNew();};
bind=function(){UI2.bind();if(el('menuStore'))el('menuStore').onchange=()=>{menuStore=el('menuStore').value;render()};on('[data-menu-item]',i=>act(()=>{const s=state.stores.find(s=>s.id===menuStore),key=i.dataset.menuItem,item={...s.menu[key]};item[i.dataset.menuKey]=i.dataset.menuKey==='price'?Number(i.value):i.checked;updateMenu(s.id,key,item);if(s.manager)s.auto.price=false;},'Menu uloženo.'),'change');on('[data-equipment]',b=>{const key=b.dataset.equipment;if(b.dataset.equipped==='true')act(()=>serviceEquipment(menuStore,key),'Zařízení po servisu.');else confirmAction('Pořídit '+EQUIPMENT[key].name+'?','Investice '+money(EQUIPMENT[key].cost)+' a pravidelná údržba '+money(EQUIPMENT[key].maintenance)+'/týden.',()=>buyEquipment(menuStore,key),'Pořídit vybavení')});if(el('storeLayout'))el('storeLayout').onchange=()=>act(()=>setLayout(menuStore,el('storeLayout').value),'Uspořádání změněno.');if(el('deliveryPolicy'))el('deliveryPolicy').onchange=()=>act(()=>{guard();state.deliveryPolicy=el('deliveryPolicy').value},'Zásobování upraveno.');if(el('newWarehouse'))el('newWarehouse').onclick=warehouseDialog;if(el('newRoute'))el('newRoute').onclick=routeDialog;if(el('newSupply'))el('newSupply').onclick=supplyDialog;on('[data-route-toggle]',b=>act(()=>{guard();const r=state.routes.find(r=>r.id===b.dataset.routeToggle);r.active=!r.active},'Trasa upravena.'));on('[data-supply-toggle]',b=>act(()=>{guard();const d=state.supplyDeals.find(d=>d.id===b.dataset.supplyToggle);d.active=!d.active},'Dodávky upraveny.'));on('[data-roaster-city]',i=>act(()=>{guard();const r=state.roasters.find(r=>r.id===i.dataset.roasterCity);if(r.zone!==i.value){spend(75000);r.zone=i.value;log('Přemístěna výrobní linka',r.name+' → '+r.zone)}}),'change');on('[data-incident]',b=>act(()=>resolveIncident(b.dataset.incident,b.dataset.solution),'Problém vyřešen.'));on('[data-offer]',b=>act(()=>resolveOffer(b.dataset.offer,b.dataset.answer),'Nabídka vyřízena.'));for(const key of ['autoCrises','autoRetention','crisisLimit','retentionLimit'])if(el(key))el(key).onchange=()=>act(()=>{guard();const i=el(key),boolean=key.startsWith('auto'),n=boolean?i.checked:Number(i.value);if(!boolean&&(!Number.isInteger(n)||n<0||n>(key==='crisisLimit'?100000:50000)))throw Error('Neplatný limit.');state.policy3[key]=n},'Pravomoci vedení uloženy.');on('[data-train]',b=>trainingDialog(b.dataset.train));on('[data-raise]',b=>act(()=>raisePerson(b.dataset.raise),'Mzda upravena.'));on('[data-promote]',b=>promotionDialog(b.dataset.promote));on('[data-bid]',b=>act(()=>{const a=state.auctions.find(a=>a.id===b.dataset.bid);bidAuction(a.id,a.highest+10000)},'Příhoz přijat.'));if(el('acceptBuyout'))el('acceptBuyout').onclick=()=>confirmAction('Prodat celou firmu?','Kampaň skončí a dostaneš svůj podíl z '+money(state.buyout.amount)+'. Současnou hru si můžeš nejprve uložit.',()=>resolveBuyout(true),'Prodat firmu');if(el('declineBuyout'))el('declineBuyout').onclick=()=>act(()=>resolveBuyout(false),'Pokračuješ ve vlastní firmě.');if(el('planKind'))el('planKind').onchange=()=>{planningKind=el('planKind').value;planningResult=null;planDraft=null;render()};if(el('runPlan'))el('runPlan').onclick=()=>{try{planDraft=readPlan();planningResult=simulatePlan(planDraft,Number(el('planWeeks').value));render();toast('Výhled spočítán. Rozehraná firma zůstala v aktuálním týdnu.')}catch(e){toast(e.message)}};if(el('commitPlan'))el('commitPlan').onclick=()=>{const plan=planningResult.plan;confirmAction('Provést investici?','Aktuální cena '+money(planCost(plan))+'. Výhled je odhad; skutečné výsledky závisí na dalších rozhodnutích.',()=>{applyPlan(plan);planningResult=null},'Investovat')};if(el('chooseScenario'))el('chooseScenario').onclick=()=>confirmNew();on('[data-new-scenario]',b=>confirmNew(b.dataset.newScenario));};
el('help').onclick=help;el('newgame').onclick=()=>confirmNew();el('next').onclick=()=>{const previous=state.scenarioWon,h=act(nextWeek);if(h){toast('Týden uzavřen: '+money(h.profit));if(state.over||state.scenarioWon&&!previous){show(`<h2>${state.sold?'Firma byla prodána':state.over?'Firma nemá hotovost':'Scénář dokončen!'}</h2><p>${state.over?'Načti starší postup nebo začni novou kampaň.':SCENARIOS[state.scenario].name+' splňuje svůj cíl. Můžeš dál rozvíjet firmu.'}</p><button class="soft" id="finishHelp">Ukládání & nová kampaň</button>`);el('finishHelp').onclick=help}}};
render();
const CITY3=cityView;
cityView=function(){const html=CITY3(),a=state.auctions.find(a=>!a.closed&&a.location===selected);if(!a)return html;return `<div class="tutorial"><span>O ${loc(a.location).name} probíhá aukce do týdne ${a.due}. Nejvyšší příhoz ${money(a.highest)}; otevření vyžaduje výhru.</span><button class="soft mini" data-goto="rivals">Přejít do aukce →</button></div>`+html.replace('data-open="'+selected+'"','data-open="'+selected+'" disabled').replace('data-franchise="'+selected+'"','data-franchise="'+selected+'" disabled')};
render();
